SELECT a.tenant_id, a.target_principal_id AS entity_id, a.event_id || '|' || b.event_id AS evidence_ids FROM events a JOIN events b ON b.tenant_id=a.tenant_id AND b.domain='cloud-azure' AND b.phase=1 AND b.action='secret_read' AND b.principal_id=a.target_principal_id AND b.ts-a.ts BETWEEN :min_order_gap AND 900 WHERE a.phase=1 AND a.domain='cloud-azure' AND a.action='role_granted' AND a.is_privileged=1 AND a.approved=0 AND b.is_sensitive=1;
